/* =========================================================
   ESTADO
   ========================================================= */
let currentQuery = "";
let currentCategory = "todas";
let currentDepartamento = "Santa Ana";

// Para el departamento elegido, solo devuelve las rutas que ya tienen
// ficha completa (recorrido, tarifa y mapa) verificada en Cartorux.
// Las rutas sin ficha completa no se muestran acá: quedan solo en el
// índice de "Rutas por departamento" más abajo, junto a su número.

/* ---- Display helpers (English UI; internal data keys stay in Spanish so filters keep working) ---- */
const CATEGORY_EN = { Urbana: "Urban", Interurbana: "Interurban", Interdepartamental: "Interdepartmental" };
const catEn = (c) => CATEGORY_EN[c] || c;
const routeEn = (n) => String(n).replace(/^Ruta\s+/i, "Route ");
const fareEn = (t) => String(t)
  .replace("No especificada por Cartorux", "Not specified by Cartorux")
  .replace("servicio ordinario", "regular service")
  .replace("servicio especial directo, con aire acondicionado", "special direct service, air-conditioned")
  .replace("variable por tramo largo", "varies on long stretches")
  .replace("(variable)", "(varies)")
  .replace("Microbús", "Minibus")
  .replace(" y ", " and ");

function getCardsForDepartment(nombreDepartamento) {
  return ROUTES.filter((r) => r.departamento === nombreDepartamento);
}

/* =========================================================
   REFERENCIAS AL DOM
   ========================================================= */
const gridEl = document.getElementById("routes-grid");
const emptyStateEl = document.getElementById("empty-state");
const resultsCountEl = document.getElementById("results-count");
const searchInput = document.getElementById("route-search");
const clearBtn = document.getElementById("clear-search");
const chips = document.querySelectorAll(".chip");
const topDeptSelect = document.getElementById("top-dept-select");

const mapModal = document.getElementById("map-modal");
const mapModalBackdrop = document.getElementById("map-modal-backdrop");
const mapModalClose = document.getElementById("map-modal-close");
const mapModalTitle = document.getElementById("map-modal-title");
const mapModalCategory = document.getElementById("map-modal-category");
const mapModalNote = document.getElementById("map-modal-note");

/* =========================================================
   UTILIDADES
   ========================================================= */

// Quita acentos y pasa a minúsculas para que "Metrocentro" === "metrocentro" === "métrocentro"
function normalize(text) {
  return text
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

// Envuelve en <mark> la porción del texto que coincide con la búsqueda, preservando el texto original
function highlightMatch(text, query) {
  if (!query) return text;

  const normalizedText = normalize(text);
  const normalizedQuery = normalize(query);
  const index = normalizedText.indexOf(normalizedQuery);

  if (index === -1) return text;

  const before = text.slice(0, index);
  const match = text.slice(index, index + query.length);
  const after = text.slice(index + query.length);

  return `${before}<mark>${match}</mark>${after}`;
}

// Determina si una ruta coincide con la búsqueda: por número o por lugar de paso
function matchesQuery(route, query) {
  if (!query) return true;
  const q = normalize(query);
  const haystack = normalize(
    `${route.numero} ${route.origenDestino || ""} ${route.recorrido || ""}`
  );
  return haystack.includes(q);
}

function matchesCategory(route, category) {
  return category === "todas" || route.categoria === category;
}

/* =========================================================
   RENDERIZADO
   ========================================================= */

// Mapea cada categoría de ruta a su variable de color CSS correspondiente
const CATEGORY_COLOR_VAR = {
  Urbana: "--color-urbana",
  Interurbana: "--color-interurbana",
  Interdepartamental: "--color-interdep"
};

function createRouteCard(route) {
  const article = document.createElement("article");
  article.className = "route-card";
  const colorVar = CATEGORY_COLOR_VAR[route.categoria] || "--color-urbana";
  article.style.setProperty("--card-accent", `var(${colorVar})`);

  article.innerHTML = `
    <div class="route-card-head">
      <span class="route-badge">${routeEn(route.numero)}</span>
      <div class="route-heading">
        <p class="route-category">${catEn(route.categoria)}</p>
        <p class="route-endpoints">${highlightMatch(route.origenDestino, currentQuery)}</p>
      </div>
    </div>
    <div class="route-body">
      <p class="route-section-label">Route</p>
      <p class="route-stops">${highlightMatch(route.recorrido, currentQuery)}</p>
    </div>
    <div class="route-footer">
      <span class="route-fare-label">Fare</span>
      <span class="route-fare-value">${fareEn(route.tarifa)}</span>
    </div>
    <button type="button" class="route-map-btn" data-route-id="${route.id}">
      <svg viewBox="0 0 24 24"><path d="M9 20l-5.447-2.724A1 1 0 0 1 3 16.382V5.618a1 1 0 0 1 1.447-.894L9 7m0 13l6-3m-6 3V7m6 10l4.553 2.276A1 1 0 0 0 21 18.382V7.618a1 1 0 0 0-.553-.894L15 4m0 13V4m0 0L9 7"/></svg>
      View route on map
    </button>
  `;

  const mapButton = article.querySelector(".route-map-btn");
  mapButton.addEventListener("click", () => openRouteMap(route));

  return article;
}

function render() {
  const source = getCardsForDepartment(currentDepartamento);
  const filtered = source.filter(
    (route) => matchesQuery(route, currentQuery) && matchesCategory(route, currentCategory)
  );

  gridEl.innerHTML = "";

  if (filtered.length === 0) {
    emptyStateEl.hidden = false;
  } else {
    emptyStateEl.hidden = true;
    const fragment = document.createDocumentFragment();
    filtered.forEach((route) => fragment.appendChild(createRouteCard(route)));
    gridEl.appendChild(fragment);
  }

  updateResultsCount(filtered.length);
  clearBtn.hidden = currentQuery.length === 0;
}

function updateResultsCount(count) {
  const prefix = `${currentDepartamento}: `;
  if (currentQuery || currentCategory !== "todas") {
    resultsCountEl.textContent =
      count === 1 ? `${prefix}1 route found` : `${prefix}${count} routes found`;
  } else {
    resultsCountEl.textContent = `${prefix}showing all ${count} available routes`;
  }
}

/* =========================================================
   EVENTOS
   ========================================================= */
searchInput.addEventListener("input", (event) => {
  currentQuery = event.target.value.trim();
  render();
});

clearBtn.addEventListener("click", () => {
  currentQuery = "";
  searchInput.value = "";
  searchInput.focus();
  render();
});

chips.forEach((chip) => {
  chip.addEventListener("click", () => {
    chips.forEach((c) => c.classList.remove("is-active"));
    chip.classList.add("is-active");
    currentCategory = chip.dataset.filter;
    render();
  });
});

topDeptSelect.addEventListener("change", (event) => {
  currentDepartamento = event.target.value;
  render();
  deptSelectEl.value = currentDepartamento;
  renderDeptDetail(currentDepartamento);
});

/* =========================================================
   MAPA DEL RECORRIDO (Leaflet + OSRM)
   =========================================================
   Cómo funciona:
   1. Cada ruta tiene "waypoints": puntos de referencia aproximados en orden.
   2. Al abrir el mapa, se pide a un servicio de ruteo (OSRM) que calcule
      el camino real sobre las calles que conecta esos puntos, en vez de
      trazar líneas rectas entre ellos.
   3. Cuando tengas datos GPS reales (ver nota al final de este archivo),
      podés reemplazar "waypoints" por la traza real y omitir el paso 2,
      o dejar ambos como respaldo si el GPX tiene huecos.
*/

let leafletMap = null;
let leafletRouteLayer = null;
let leafletMarkersLayer = null;

function ensureMapInitialized() {
  if (leafletMap) return;

  leafletMap = L.map("leaflet-map", {
    scrollWheelZoom: false
  });

  L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
    maxZoom: 19,
    attribution: "&copy; colaboradores de OpenStreetMap"
  }).addTo(leafletMap);

  leafletRouteLayer = L.layerGroup().addTo(leafletMap);
  leafletMarkersLayer = L.layerGroup().addTo(leafletMap);
}

// Construye la URL de OSRM: lng,lat separados por ";" en el orden del recorrido
function buildOsrmUrl(waypoints) {
  const coords = waypoints.map((p) => `${p.lng},${p.lat}`).join(";");
  return `https://router.project-osrm.org/route/v1/driving/${coords}?overview=full&geometries=geojson`;
}

// Dibuja un recorrido a partir de una traza GPS real (ida y, si existe, regreso)
function drawRealTracks(tracks) {
  leafletRouteLayer.clearLayers();

  const idaLine = L.polyline(tracks.ida, {
    color: "#204d78",
    weight: 5,
    opacity: 0.9
  }).addTo(leafletRouteLayer);

  let bounds = idaLine.getBounds();

  if (tracks.regreso && tracks.regreso.length > 0) {
    const regresoLine = L.polyline(tracks.regreso, {
      color: "#f2a93b",
      weight: 4,
      opacity: 0.9,
      dashArray: "2 10"
    }).addTo(leafletRouteLayer);
    bounds = bounds.extend(regresoLine.getBounds());
  }

  mapModalNote.innerHTML = tracks.regreso
    ? 'Real route (official GPS track). <span style="color:#204d78">&#9644;</span> Outbound &nbsp; <span style="color:#f2a93b">&#9644;</span> Return'
    : "Real route (official GPS track).";

  return bounds;
}

async function drawRealStreetRoute(waypoints) {
  leafletRouteLayer.clearLayers();

  try {
    const response = await fetch(buildOsrmUrl(waypoints));
    if (!response.ok) throw new Error("Routing service did not respond correctly");

    const data = await response.json();
    const coordsGeoJson = data.routes?.[0]?.geometry?.coordinates;

    if (!coordsGeoJson || coordsGeoJson.length === 0) {
      throw new Error("No route geometry");
    }

    // GeoJSON usa [lng, lat]; Leaflet espera [lat, lng]
    const latLngs = coordsGeoJson.map(([lng, lat]) => [lat, lng]);
    const polyline = L.polyline(latLngs, {
      color: "#204d78",
      weight: 5,
      opacity: 0.85
    }).addTo(leafletRouteLayer);

    mapModalNote.textContent =
      "Route calculated over real streets (OSRM) from the route's reference points.";

    return polyline.getBounds();
  } catch (error) {
    // Respaldo: si el servicio de ruteo falla (sin internet, límite de uso, etc.)
    // se traza una línea recta entre los puntos para que el mapa siga siendo útil.
    const latLngs = waypoints.map((p) => [p.lat, p.lng]);
    const polyline = L.polyline(latLngs, {
      color: "#204d78",
      weight: 4,
      opacity: 0.7,
      dashArray: "6 8"
    }).addTo(leafletRouteLayer);

    mapModalNote.textContent =
      "We couldn't calculate the route on real streets right now; an approximate line between reference points is shown.";

    return polyline.getBounds();
  }
}

function openRouteMap(route) {
  mapModal.hidden = false;
  document.body.style.overflow = "hidden";
  mapModalTitle.textContent = `${routeEn(route.numero)} — ${route.origenDestino}`;
  mapModalCategory.textContent = catEn(route.categoria);
  mapModalNote.textContent = route.tracks
    ? "Loading the real route…"
    : "Calculating the route on real streets…";

  // Leaflet necesita que su contenedor sea visible antes de inicializarse correctamente
  requestAnimationFrame(() => {
    ensureMapInitialized();
    leafletMap.invalidateSize();
    leafletMarkersLayer.clearLayers();

    if (route.tracks) {
      // Ruta con datos GPS reales: los marcadores son el inicio y el final de la ida
      const start = route.tracks.ida[0];
      const end = route.tracks.ida[route.tracks.ida.length - 1];

      L.circleMarker(start, {
        radius: 7,
        color: "#142c47",
        fillColor: "#f2a93b",
        fillOpacity: 1,
        weight: 2
      })
        .bindTooltip("Route start")
        .addTo(leafletMarkersLayer);

      L.circleMarker(end, {
        radius: 7,
        color: "#142c47",
        fillColor: "#f2a93b",
        fillOpacity: 1,
        weight: 2
      })
        .bindTooltip("Route end")
        .addTo(leafletMarkersLayer);

      const bounds = drawRealTracks(route.tracks);
      if (bounds) leafletMap.fitBounds(bounds, { padding: [30, 30] });
      return;
    }

    // Ruta sin datos GPS todavía: se usan los puntos de referencia aproximados + OSRM
    route.waypoints.forEach((point, index) => {
      const isEndpoint = index === 0 || index === route.waypoints.length - 1;
      L.circleMarker([point.lat, point.lng], {
        radius: isEndpoint ? 7 : 5,
        color: "#142c47",
        fillColor: isEndpoint ? "#f2a93b" : "#3b7ab0",
        fillOpacity: 1,
        weight: 2
      })
        .bindTooltip(point.label)
        .addTo(leafletMarkersLayer);
    });

    drawRealStreetRoute(route.waypoints).then((bounds) => {
      if (bounds) {
        leafletMap.fitBounds(bounds, { padding: [30, 30] });
      }
    });
  });
}

function closeRouteMap() {
  mapModal.hidden = true;
  document.body.style.overflow = "";
}

mapModalClose.addEventListener("click", closeRouteMap);
mapModalBackdrop.addEventListener("click", closeRouteMap);
__listen(document, "keydown", (event) => {
  if (event.key === "Escape" && !mapModal.hidden) closeRouteMap();
});

/* =========================================================
   RUTAS POR DEPARTAMENTO (ÍNDICE DE CARTORUX)
   ========================================================= */
const deptSelectEl = document.getElementById("dept-select");
const deptInfoEl = document.getElementById("dept-info");
const deptListsEl = document.getElementById("dept-lists");
const deptSearchInput = document.getElementById("dept-route-search");
const deptSearchResultsEl = document.getElementById("dept-search-results");

function renderDeptOptions() {
  deptSelectEl.innerHTML = DEPARTAMENTOS.map(
    (dep) => `<option value="${dep.nombre}">${dep.nombre}</option>`
  ).join("");
}

function totalRutas(dep) {
  return (
    dep.rutas.Interdepartamental.length +
    dep.rutas.Interurbana.length +
    dep.rutas.Urbana.length
  );
}

function renderDeptDetail(nombreDepartamento) {
  const dep = DEPARTAMENTOS.find((d) => d.nombre === nombreDepartamento);
  if (!dep) return;

  const completas = new Set(
    ROUTES.filter((r) => r.departamento === nombreDepartamento).map((r) =>
      r.numero.replace(/^Ruta\s+/i, "")
    )
  );

  deptInfoEl.innerHTML = `<strong>${dep.nombre}</strong> · ${dep.zona} zone · ${dep.municipios} municipalities / ${dep.distritos} districts · ${totalRutas(dep)} routes registered in Cartorux, ${completas.size} with full details (route, fare and map) above`;

  const categorias = [
    { key: "Interdepartamental", label: "Interdepartmental" },
    { key: "Interurbana", label: "Interurban" },
    { key: "Urbana", label: "Urban" }
  ];

  deptListsEl.innerHTML = categorias
    .map(({ key, label }) => {
      const lista = dep.rutas[key];
      const colorVar = CATEGORY_COLOR_VAR[key] || "--color-urbana";
      const badges = lista.length
        ? lista
            .map((num) => {
              const isComplete = completas.has(num);
              return `<span class="dept-route-badge${isComplete ? " dept-route-badge--complete" : ""}" title="${isComplete ? "Full details available above" : "Only listed by Cartorux, full details coming soon"}">${num}${isComplete ? " ✓" : ""}</span>`;
            })
            .join("")
        : `<span class="dept-route-badge">— no routes listed —</span>`;

      return `
        <div class="dept-category-card" style="--card-accent: var(${colorVar})">
          <p class="dept-category-title">${label}</p>
          <p class="dept-category-count">${lista.length} route${lista.length === 1 ? "" : "s"}</p>
          <div class="dept-badge-list">${badges}</div>
        </div>
      `;
    })
    .join("");
}

function searchRouteAcrossDepartments(query) {
  const q = normalize(query.trim());
  if (!q) {
    deptSearchResultsEl.hidden = true;
    deptSearchResultsEl.innerHTML = "";
    return;
  }

  const matches = [];
  DEPARTAMENTOS.forEach((dep) => {
    Object.entries(dep.rutas).forEach(([categoria, lista]) => {
      lista.forEach((numero) => {
        if (normalize(numero).includes(q)) {
          matches.push({ departamento: dep.nombre, categoria, numero });
        }
      });
    });
  });

  deptSearchResultsEl.hidden = false;

  if (matches.length === 0) {
    deptSearchResultsEl.innerHTML = `No route matching "${query}" was found in the Cartorux index.`;
    return;
  }

  const grouped = matches.reduce((acc, m) => {
    acc[m.departamento] = acc[m.departamento] || [];
    acc[m.departamento].push(`Route ${m.numero} (${catEn(m.categoria)})`);
    return acc;
  }, {});

  deptSearchResultsEl.innerHTML =
    `<strong>${matches.length} match${matches.length === 1 ? "" : "es"} for "${query}":</strong><br>` +
    Object.entries(grouped)
      .map(([depName, items]) => `${depName}: ${items.join(", ")}`)
      .join("<br>");
}

deptSelectEl.addEventListener("change", (e) => {
  const value = e.target.value;
  renderDeptDetail(value);
  currentDepartamento = value;
  topDeptSelect.value = value;
  render();
});
deptSearchInput.addEventListener("input", (e) => searchRouteAcrossDepartments(e.target.value));

function initDepartmentsSection() {
  renderDeptOptions();
  renderDeptDetail("Santa Ana");

  topDeptSelect.innerHTML = DEPARTAMENTOS.map(
    (dep) => `<option value="${dep.nombre}">${dep.nombre}</option>`
  ).join("");
  topDeptSelect.value = currentDepartamento;
}

/* =========================================================
   INICIO
   ========================================================= */
initDepartmentsSection();
render();

/* =========================================================
   NOTA SOBRE PRECISIÓN DE DATOS
   =========================================================
   Las coordenadas en "waypoints" son aproximaciones basadas en los nombres
   de los lugares mencionados en el recorrido de cada ruta, no en datos GPS
   verificados. Para reemplazarlas por datos reales:

   1. Grabá cada recorrido con una app de GPS mientras viajás en el bus,
      de inicio a fin (apps gratuitas: OsmAnd, Geo Tracker, Gaia GPS).
   2. Exportá la grabación como archivo .gpx.
   3. Convertí el .gpx a una lista de coordenadas [lat, lng] — por ejemplo,
      con la librería gratuita "togeojson" o el conversor en línea
      mygeodata.cloud/converter/gpx-to-json.
   4. Reemplazá el arreglo "waypoints" de esa ruta por la traza real
      (podés dejar solo unos 10-20 puntos representativos del trayecto,
      no hace falta cada punto del GPX, para que OSRM calcule mejor).
*/

/* [migración] listener del carrusel de main.js eliminado */

__ready( () => {
    updateRotativeCarousel();
    startAutoPlay();

    const menuToggle = document.getElementById('menuToggle');
    const navLinks = document.getElementById('navLinks');

    menuToggle?.addEventListener('click', (e) => {
        e.stopPropagation(); 
        navLinks?.classList.toggle('active');
        
        const icon = menuToggle.querySelector('i');
        if (icon) {
            icon.classList.toggle('fa-bars');
            icon.classList.toggle('fa-times');
        }
    });

    __listen(document, 'click', (e) => {
        if (navLinks?.classList.contains('active') && !navLinks.contains(e.target) && e.target !== menuToggle) {
            navLinks.classList.remove('active');
            const icon = menuToggle?.querySelector('i');
            if (icon) {
                icon.classList.add('fa-bars');
                icon.classList.remove('fa-times');
            }
        }
    });
});


